import {ServerTransport} from "./ServerTransport.js";
import {Flusher} from "./Flusher.js";
import {Utils} from "./Utils.js";
import * as crypto from "node:crypto";

export class HTTPTransport extends ServerTransport {
    #prefix = "long-polling.json";
    #sessions = {};
    #browserMetaConnects = {};
    #requests = 0;

    constructor(cometd) {
        super(cometd)
    }

    get name() {
        return "long-polling";
    }

    option(name) {
        const result = super.option(name);
        if (result !== undefined) {
            return result;
        }
        let dftValue = undefined;
        switch (name) {
            case "browserCookieName":
                dftValue = "BAYEUX_BROWSER";
                break;
            case "browserCookieHttpOnly":
                dftValue = true;
                break;
            case "maxSessionsPerBrowser":
                dftValue = 1;
                break;
            case "multiSessionInterval":
                dftValue = 2000;
                break;
            case "duplicateMetaConnectHttpResponseCode":
                dftValue = 500;
                break;
        }
        return this._option(this.#prefix, name, dftValue);
    };

    handle(request, response) {
        if (request.method === "POST") {
            if (request.body) {
                this.#process(request, response, request.body);
            } else {
                let content = "";
                // TODO: limit message size.
                request.addListener("data", chunk => {
                    content += chunk;
                });
                request.addListener("end", () => {
                    try {
                        this.#process(request, response, JSON.parse(content));
                    } catch (failure) {
                        this._log(failure.stack);
                        response.statusCode = 400;
                        response.end();
                    }
                });
                ["aborted", "error"].forEach(event => {
                    request.addListener(event, e => {
                        this._log("request", event);
                        response._cometd_request_error = e ? e : new Error("request error");
                    });
                });
            }
        } else {
            response.statusCode = 400;
            response.end();
        }
    };


    // PRIVATE APIs


    #process(request, response, messages) {
        // Sets the context used by applications, so that
        // they can access Node's request and response.
        this.cometd._setContext({
            request: request,
            response: response
        });
        this.#processMessages(request, response, messages, () => {
            this.cometd._setContext(null);
        });
    }

    #processMessages(request, response, messages, callback) {
        // An internal context used by the implementation to avoid
        // modifying/altering that given to applications via cometd.context.
        const context = {
            id: ++this.#requests,
            request: request,
            response: response
        };

        this._log("processing request", "#" + context.id, "messages:", messages.length);

        if (messages.length === 0) {
            this._log("invalid request", "#" + context.id, "no messages");
            response.statusCode = 400;
            response.end();
            callback();
            return;
        }

        const cookies = context.cookies = this.#parseCookies(request.headers.cookie);
        const sessions = this.#findSessions(cookies);
        const message = messages[0];
        const session = this.#findSession(sessions, message);
        this._log("session", session ? session.id : "null");
        const batch = session && message.channel !== "/meta/connect";
        if (batch) {
            session._startBatch();
        }

        const local = {
            sendQueue: false,
            replies: [],
            scheduleExpiration: false
        };

        Utils.asyncFoldLeft(messages, undefined, (ignored, message, loop) => {
            this._log("processing", message);
            switch (message.channel) {
                case "/meta/handshake": {
                    this.#processMetaHandshake(context, session, message, failure => {
                        if (failure) {
                            loop(failure);
                        } else {
                            if (messages.length > 1) {
                                loop(new Error("protocol violation"));
                            } else {
                                this.cometd._extendReply(session, message.reply, (failure, reply) => {
                                    if (failure) {
                                        loop(failure);
                                    } else {
                                        reply = Utils.serialize(reply);
                                        this._log("reply", reply);
                                        if (reply) {
                                            local.replies.push(reply);
                                        }
                                        local.sendQueue = false;
                                        local.scheduleExpiration = true;
                                        loop();
                                    }
                                });
                            }
                        }
                    });
                    break;
                }
                case "/meta/connect": {
                    const canSuspend = messages.length === 1;
                    this.#processMetaConnect(context, session, message, canSuspend, failure => {
                        if (failure) {
                            loop(failure);
                        } else {
                            this.cometd._extendReply(session, message.reply, (failure, reply) => {
                                if (failure) {
                                    loop(failure);
                                } else {
                                    reply = Utils.serialize(reply);
                                    this._log("reply", reply);
                                    if (reply) {
                                        local.replies.push(reply);
                                    }
                                    local.sendQueue = true;
                                    local.scheduleExpiration = true;
                                    loop();
                                }
                            });
                        }
                    });
                    break;
                }
                default: {
                    this.cometd._process(session, message, failure => {
                        if (failure) {
                            loop(failure);
                        } else {
                            this.cometd._extendReply(session, message.reply, (failure, reply) => {
                                if (failure) {
                                    loop(failure);
                                } else {
                                    reply = Utils.serialize(reply);
                                    this._log("reply", reply);
                                    if (reply) {
                                        local.replies.push(reply);
                                    }
                                    local.sendQueue = !(session && session._metaConnectDeliveryOnly);
                                    // Leave scheduleExpiration unchanged.
                                    loop();
                                }
                            });

                        }
                    });
                }
            }
        }, failure => {
            if (failure) {
                if (response.statusCode < 400) {
                    response.statusCode = 500;
                }
                this._log("request", "#" + context.id, "failure", response.statusCode, "for session", session ? session.id : "null", failure);
                response.end();
                callback(failure);
            } else {
                this.#respond(context, local, session, callback);
            }
            if (batch) {
                session._endBatch();
            }
        });
    }

    #parseCookies(text) {
        const cookies = {};
        if (text) {
            text.split(";").forEach(cookie => {
                const parts = cookie.split("=");
                if (parts.length > 1) {
                    const name = parts[0].trim();
                    cookies[name] = parts[1].trim();
                }
            });
        }
        return cookies;
    }

    #generateCookie(cookieName, cookieValue) {
        let result = cookieName + "=" + cookieValue;
        const domain = this.option("browserCookieDomain");
        if (domain) {
            result += "; Domain=" + domain;
        }
        const path = this.option("browserCookiePath");
        if (path) {
            result += "; Path=" + path;
        }
        const maxAge = this.option("browserCookieMaxAge");
        if (maxAge) {
            result += "; Max-Age=" + maxAge;
        }
        if (this.option("browserCookieHttpOnly") === true) {
            result += "; HttpOnly";
        }
        if (this.option("browserCookieSecure") === true) {
            result += "; Secure";
        }
        const sameSite = this.option("browserCookieSameSite");
        if (sameSite) {
            result += "; SameSite=" + sameSite;
        }
        if (this.option("browserCookiePartitioned") === true) {
            result += "; Partitioned";
        }
        return result;
    }

    #findSessions(cookies) {
        for (const cookie in cookies) {
            if (Object.prototype.hasOwnProperty.call(cookies, cookie)) {
                if (cookie === this.option("browserCookieName")) {
                    const browserId = cookies[cookie];
                    return this.#sessions[browserId] || null;
                }
            }
        }
        return null;
    }

    #findSession(sessions, message) {
        if (message.channel === "/meta/handshake") {
            return this.cometd._newServerSession();
        }
        if (sessions) {
            const sessionId = message.clientId;
            for (let i = 0; i < sessions.length; ++i) {
                const session = sessions[i];
                if (session.id === sessionId) {
                    return session;
                }
            }
        }
        return null;
    }

    #processMetaHandshake(context, session, message, callback) {
        this.cometd._process(session, message, failure => {
            if (failure) {
                callback(failure);
            } else {
                const reply = message.reply;
                if (reply.successful) {
                    const cookieName = this.option("browserCookieName");
                    let browserId = context.cookies[cookieName];
                    if (!browserId) {
                        browserId = crypto.randomBytes(20).toString("hex");
                        context.response.setHeader("Set-Cookie", this.#generateCookie(cookieName, browserId));
                    }
                    let list = this.#sessions[browserId];
                    if (!list) {
                        list = [];
                        this.#sessions[browserId] = list;
                    }
                    list.push(session);
                    session._browserId = browserId;

                    session.addListener("removed", () => {
                        const i = list.indexOf(session);
                        if (i >= 0) {
                            list.splice(i, 1);
                        }
                        if (list.length === 0) {
                            delete this.#sessions[browserId];
                            delete this.#browserMetaConnects[browserId];
                        }
                    });
                    this.#advise(reply);
                }
                callback();
            }
        });
    }

    #advise(reply) {
        let advice = reply.advice;
        if (!advice) {
            advice = reply.advice = {};
        }
        advice.reconnect = "retry";
        advice.timeout = this.option("timeout");
        advice.interval = this.option("interval");
    }

    #processMetaConnect(context, session, message, canSuspend, callback) {
        if (session) {
            const flusher = session._flusher;
            if (flusher) {
                flusher.cancel();
            }
        }

        this.cometd._process(session, message, failure => {
            if (failure) {
                callback(failure);
            } else {
                const maySuspend = session && (!session._hasMessages || session._isBatching);
                const reply = message.reply;
                if (canSuspend && maySuspend && reply.successful) {
                    const allowSuspend = this.#addBrowserMetaConnect(session);
                    if (allowSuspend) {
                        if (message.advice) {
                            this.#advise(reply);
                        }
                        const timeout = session._calculateTimeout(this.option("timeout"));
                        if (timeout > 0) {
                            const flusher = new HTTPFlusher(this, context, callback, session, message);
                            flusher._schedule(timeout);
                            session._flusher = flusher;
                            this._log("suspended", message);
                            Utils.notifyEvent(session.listeners("suspended"), [session, message, timeout]);
                        } else {
                            this._removeBrowserMetaConnect(session);
                            callback();
                        }
                    } else {
                        let advice = reply.advice;
                        if (!advice) {
                            advice = reply.advice = {};
                        }
                        advice["multiple-clients"] = true;

                        const multiSessionInterval = this.option("multiSessionInterval");
                        if (multiSessionInterval > 0) {
                            advice.reconnect = "retry";
                            advice.interval = multiSessionInterval;
                        } else {
                            reply.successful = false;
                            advice.reconnect = "none";
                        }
                        callback();
                    }
                } else {
                    callback();
                }
            }
        });
    }

    #addBrowserMetaConnect(session) {
        const maxSessionsPerBrowser = this.option("maxSessionsPerBrowser");
        if (maxSessionsPerBrowser < 0) {
            return true;
        } else if (maxSessionsPerBrowser === 0) {
            return false;
        }
        const browserId = session._browserId;
        let count = this.#browserMetaConnects[browserId];
        if (count === undefined) {
            count = this.#browserMetaConnects[browserId] = 0;
        }
        if (count === maxSessionsPerBrowser) {
            return false;
        }
        ++this.#browserMetaConnects[browserId];
        return true;
    }

    _removeBrowserMetaConnect(session) {
        const maxSessionsPerBrowser = this.option("maxSessionsPerBrowser");
        if (maxSessionsPerBrowser > 0) {
            const browserId = session._browserId;
            const count = this.#browserMetaConnects[browserId];
            if (count !== undefined) {
                --this.#browserMetaConnects[browserId];
            }
        }
    }

    #respond(context, local, session, callback) {
        const response = context.response;
        response.statusCode = 200;
        response.setHeader("Content-Type", "application/json");

        let content = "[";
        // Serialize the queue.
        let queue = [];
        if (session && local.sendQueue) {
            queue = session._drainQueue(local.replies);
            this._log("sending", queue.length, "queued messages for", session.id);
            queue.forEach((m, i) => {
                if (i > 0) {
                    content += ",";
                }
                let json = m._json;
                if (!json) {
                    json = JSON.stringify(m);
                }
                content += json;
            });
        }
        // Serialize the replies.
        this._log("sending", local.replies.length, "replies for session", session ? session.id : "null");
        local.replies.forEach((reply, i) => {
            if (i === 0) {
                if (queue.length > 0) {
                    content += ",";
                }
            } else if (i > 0) {
                content += ",";
            }
            let json = reply._json;
            if (!json) {
                json = JSON.stringify(reply);
            }
            content += json;
        });
        content += "]";

        const finish = failure => {
            this._log("request", "#" + context.id, "finish for session", session ? session.id : "null");
            if (session && local.scheduleExpiration) {
                session._scheduleExpiration(this.option("interval"), this.option("maxInterval"));
            }
            callback(failure);
        };

        response.addListener("finish", () => {
            finish();
        });
        response.addListener("error", e => {
            finish(e ? e : new Error("response error"));
        });
        const requestError = response._cometd_request_error;
        if (requestError) {
            finish(requestError);
        } else if (!response.socket || response.socket.destroyed) {
            finish(new Error("connection destroyed"));
        } else {
            response.end(content, "utf8");
        }
    }

    _log(...args) {
        this.cometd._log(this.#prefix, args);
    }
}

class HTTPFlusher extends Flusher {
    #transport;
    #context;
    #callback;
    #session;
    #message;
    #timeout;

    constructor(transport, context, callback, session, message) {
        super();
        this.#transport = transport;
        this.#context = context;
        this.#callback = callback;
        this.#session = session;
        this.#message = message;
    }

    flush() {
        if (this.#timeout) {
            clearTimeout(this.#timeout);
            this.#timeout = null;
            this.#session._flusher = null;
            Utils.notifyEvent(this.#session.listeners("resumed"), [this.#session, this.#message, false]);
            this.#transport._log("resumed wakeup", this.#message);
            this.#flush();
        }
    }

    cancel() {
        if (this.#timeout) {
            clearTimeout(this.#timeout);
            this.#timeout = null;
            this.#session._flusher = null;
            this.#transport._removeBrowserMetaConnect(this.#session);
            this.#context.response.statusCode = this.#transport.option("duplicateMetaConnectHttpResponseCode");
            this.#callback(new Error("duplicate heartbeat"));
        }
    }

    _schedule(timeout) {
        this.#timeout = setTimeout(() => {
            if (this.#timeout) {
                this.#timeout = null;
                this.#session._flusher = null;
                Utils.notifyEvent(this.#session.listeners("resumed"), [this.#session, this.#message, true]);
                this.#transport._log("resumed expire", this.#message);
                this.#flush();
            }
        }, timeout);
    }

    #flush() {
        this.#transport._removeBrowserMetaConnect(this.#session);
        this.#callback();
    }
}
